function decodeHashMarks(code: string): string {
  const out: string[] = [];
  let i = 0;
  while (i < code.length) {
    if (i + 2 < code.length && code[i + 2] === "#") {
      out.push(String.fromCharCode(96 + Number(code.slice(i, i + 2))));
      i += 3;
    } else {
      out.push(String.fromCharCode(96 + Number(code[i])));
      i += 1;
    }
  }
  return out.join("");
}

