function decodeHashMarks(code: string): string {
  const out: string[] = [];
  let i = code.length - 1;
  while (i >= 0) {
    if (code[i] === "#") {
      out.push(String.fromCharCode(96 + Number(code.slice(i - 2, i))));
      i -= 3;
    } else {
      out.push(String.fromCharCode(96 + Number(code[i])));
      i -= 1;
    }
  }
  return out.reverse().join("");
}

